import pytest
from operations import Calculator

@pytest.fixture
def calc() -> Calculator:
    return Calculator()

def test_add(calc: Calculator) -> None:
    assert calc.add(2.0, 3.0) == 5.0
    assert calc.add(-1.0, 1.0) == 0.0

def test_subtract(calc: Calculator) -> None:
    assert calc.subtract(10.0, 5.0) == 5.0
    assert calc.subtract(0.0, 5.0) == -5.0

def test_multiply(calc: Calculator) -> None:
    assert calc.multiply(3.0, 4.0) == 12.0
    assert calc.multiply(5.0, 0.0) == 0.0

def test_divide(calc: Calculator) -> None:
    assert calc.divide(10.0, 2.0) == 5.0
    assert calc.divide(5.0, 2.0) == 2.5

def test_divide_by_zero(calc: Calculator) -> None:
    with pytest.raises(ValueError, match="Cannot divide by zero."):
        calc.divide(10.0, 0.0)

def test_history_is_copy(calc: Calculator) -> None:
    calc.add(1.0, 1.0)
    history = calc.get_history()
    history.append(("fake", 0.0, 0.0, 0.0))
    assert len(calc.get_history()) == 1

def test_clear_history(calc: Calculator) -> None:
    calc.add(1.0, 1.0)
    calc.subtract(5.0, 2.0)
    assert len(calc.get_history()) == 2
    calc.clear_history()
    assert len(calc.get_history()) == 0

def test_history_record_format(calc: Calculator) -> None:
    calc.multiply(2.0, 3.0)
    history = calc.get_history()
    assert history[0] == ("multiply", 2.0, 3.0, 6.0)

