import argparse
from operations import Calculator

def main():
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument(
        "--op", 
        choices=[
            'add', 'subtract', 'multiply', 'divide', 'get_history', 
            'clear_history', 'power', 'modulo', 'memory_store', 
            'memory_recall', 'memory_clear', 'evaluate'
        ], 
        required=True, 
        help="Operation to perform"
    )
    parser.add_argument("a", type=str, nargs='?', help="First operand, memory value, or expression")
    parser.add_argument("b", type=float, nargs='?', help="Second operand (for binary ops)")

    args = parser.parse_args()
    calc = Calculator()

    try:
        if args.op in ['add', 'subtract', 'multiply', 'divide', 'power', 'modulo']:
            if args.a is None or args.b is None:
                print("Error: This operation requires two arguments.")
                return
            func = getattr(calc, args.op)
            result = func(float(args.a), args.b)
            print(f"Result: {result}")

        elif args.op == 'evaluate':
            if args.a is None:
                print("Error: Evaluate requires an expression string.")
                return
            result = calc.evaluate(args.a)
