import ast
import operator
from typing import List, Tuple, Dict, Callable, Type, Union, Optional

class Calculator:
    """A robust calculator class supporting basic arithmetic, expression evaluation, and memory management."""

    _OPERATOR_MAP: Dict[Type[ast.AST], Callable] = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.Mod: operator.mod,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def __init__(self) -> None:
        """Initialize the calculator with an empty history and no memory."""
        self._history: List[Tuple[str, float, float, float]] = []
        self._memory: Optional[float] = None

    def _record(self, op: str, a: float, b: float, res: float) -> None:
        """Record an operation in the history."""
        self._history.append((op, float(a), float(b), float(res)))

    def _validate_numeric(self, *args: float) -> None:
        """Ensure all arguments are numeric."""
        for arg in args:
            if not isinstance(arg, (int, float)):
                raise TypeError(f"Operand must be numeric, received {type(arg).__name__}")

    def add(self, a: float, b: float) -> float:
        self._validate_numeric(a, b)
        res = float(a + b)
        self._record("add", a, b, res)
        return res

    def subtract(self, a: float, b: float) -> float:
        self._validate_numeric(a, b)
        res = float(a - b)
        self._record("subtract", a, b, res)
        return res

    def multiply(self, a: float, b: float) -> float:
        self._validate_numeric(a, b)
        res = float(a * b)
        self._record("multiply", a, b, res)
        return res

    def divide(self, a: float, b: float) -> float:
        self._validate_numeric(a, b)
        if b == 0.0:
            raise ValueError("Cannot divide by zero.")
        res = float(a / b)
        self._record("divide", a, b, res)
        return res

    def power(self, base: float, exponent: float) -> float:
        self._validate_numeric(base, exponent)
        # Prevent complex numbers for standard float calculator
        if base < 0 and isinstance(exponent, float) and not exponent.is_integer():
            raise ValueError("Cannot raise negative base to fractional exponent (result is complex).")
        res = float(pow(base, exponent))
        self._record("power", base, exponent, res)
        return res

    def modulo(self, a: float, b: float) -> float:
        self._validate_numeric(a, b)
        if b == 0.0:
            raise ValueError("Cannot perform modulo by zero.")
        res = float(a % b)
        self._record("modulo", a, b, res)
        return res

    def get_history(self) -> List[Tuple[str, float, float, float]]:
        return list(self._history)

    def clear_history(self) -> None:
        self._history.clear()

    def evaluate(self, expression: str) -> float:
        if not expression or len(expression) > 256:
            raise ValueError("Invalid expression length.")

        def _eval(node: ast.AST) -> float:
            if isinstance(node, ast.Constant):
                return float(node.value)
            elif isinstance(node, ast.BinOp):
                left, right = _eval(node.left), _eval(node.right)
                op_type = type(node.op)
                if op_type == ast.Div and right == 0.0:
                    raise ValueError("Division by zero in expression.")
                if op_type == ast.Mod and right == 0.0:
                    raise ValueError("Modulo by zero in expression.")
                return float(self._OPERATOR_MAP[op_type](left, right))
            elif isinstance(node, ast.UnaryOp):
                return float(self._OPERATOR_MAP[type(node.op)](_eval(node.operand)))
            raise TypeError(f"Unsupported expression node: {type(node).__name__}")

        try:
            tree = ast.parse(expression, mode='eval')
            result = _eval(tree.body)
            self._record("evaluate", 0.0, 0.0, result)
            return result
        except Exception as e:
            raise ValueError(f"Invalid expression: {e}")

    def memory_store(self, value: float) -> None:
        self._validate_numeric(value)
        self._memory = float(value)
        self._record("memory_store", float(value), 0.0, float(value))

    def memory_recall(self) -> float:
        if self._memory is None:
            raise ValueError("Memory is empty.")
        self._record("memory_recall", 0.0, 0.0, self._memory)
        return self._memory

    def memory_clear(self) -> None:
        self._memory = None
        self._record("memory_clear", 0.0, 0.0, 0.0)

